        [global::Microsoft.Azure.PowerShell.Cmdlets.CloudHealth.PSArgumentCompleterAttribute("Unplanned", "Planned", "UserInitiated")]
        string StatusReasonType { get; set; }
        /// <summary>Timestamp when the value was reported</summary>
        global::System.DateTime? StatusReportedAt { get; set; }
        /// <summary>
        /// Human-readable summary of the current availability state from Azure Resource Health.
        /// </summary>
        string StatusSummary { get; set; }
        /// <summary>Reported value of the signal</summary>
        double? StatusValue { get; set; }

    }
